def apply[F[_]: Sync, A](
    realm: String,
    store: String => F[Option[(A, String)]],
    nonceCleanupInterval: Duration = 1.hour,
    nonceStaleTime: Duration = 1.hour,
    nonceBits: Int = 160,
): AuthMiddleware[F, A] = {
  val nonceKeeper =
    new NonceKeeper(nonceStaleTime.toMillis, nonceCleanupInterval.toMillis, nonceBits)
  challenged(challenge(realm, store, nonceKeeper))
}

def receiveNonce(data: String, nc: Int): F[NonceKeeper.Reply] =
  semaphore.withPermit {
    for {
      _ <- unsafeCheckStale()
      res <- nonces.get(data) match {
        case null => F.pure(NonceKeeper.StaleReply)
        case n: NonceF[F] =>
          n.nc.modify { lastNc =>
            if (nc > lastNc) {
              (lastNc + 1, NonceKeeper.OKReply)
            } else
              (lastNc, NonceKeeper.BadNCReply)
          }
      }
    } yield res
  }

private def unsafeCheckStale(): F[Unit] =
  for {
    nowMillis <- clock.monotonic(MILLISECONDS)
    lastCleanupTime <- lastCleanupMillis.get
    result <-
      if (nowMillis - lastCleanupTime > nonceCleanupInterval.toMillis) {
        lastCleanupMillis
          .set(nowMillis)
          .flatMap { _ =>
            // Because we are using an LinkedHashMap, the keys will be returned in the order they were
            // inserted. Therefore, once we reach a non-stale value, the remaining values are also not stale.
            F.tailRecM[ju.Iterator[NonceF[F]], Unit](nonces.values().iterator()) {
              case it
                  if it.hasNext && staleTimeout.toMillis > nowMillis - it.next().createdMillis =>
                F.delay(Left {
                  it.remove()
                  it
                })
              case _ => F.delay(Right(()))
            }
          }

  private def getRandomData[F[_]](bits: Int)(implicit F: Sync[F]): F[String] =
    F.delay(new BigInteger(bits, random).toString(16))

  @nowarn("msg=parameter value")
  def gen[F[_]](blocker: Blocker, bits: Int)(implicit
      F: Sync[F],
      t: Timer[F],
      cs: ContextShift[F],
  ): F[NonceF[F]] = for {
    nc <- Ref[F].of(0)
    data <- getRandomData[F](bits)
    createdMillis <- Clock[F].monotonic(MILLISECONDS)
  } yield new NonceF(createdMillis, nc, data)
}

def local[F[_]](capacity: Int, refillEvery: FiniteDuration)(implicit
    F: Temporal[F]
): F[TokenBucket[F]] = {
  val getNanoTime = Temporal[F].monotonic.map(_.toNanos)
  val refillEveryNanos = refillEvery.toNanos
  for {
    // make sure that refillEvery is positive
    _ <- F.raiseUnless(refillEveryNanos > 0L)(
      new IllegalArgumentException("refillEvery should be > 0 nano")
    )
    creationTime <- getNanoTime
    counter <- F.ref((capacity.toDouble, creationTime))

val takeTokenAfterRefill = createBucket.flatMap { testee =>
  for {
    _ <- testee.takeToken
    unavailable <- testee.takeToken
    _ <- IO.sleep(someRefillTime)
    available <- testee.takeToken
